export const DS=4;export function hermite(t,e={}){const n=[],r=t.length,o=a=>{if(a===0&&e.m0)return e.m0;if(a===r-1&&e.m1)return e.m1;const h=t[Math.max(0,a-1)],c=t[Math.min(r-1,a+1)],u=a===0||a===r-1?1:.5;return[(c[0]-h[0])*u,(c[1]-h[1])*u]};for(let a=0;a<r-1;a++){const h=t[a],c=t[a+1],u=o(a),l=o(a+1),y=Math.hypot(c[0]-h[0],c[1]-h[1]),f=Math.max(2,Math.ceil(y/3));for(let i=a?1:0;i<=f;i++){const x=i/f,s=x*x,p=s*x,m=2*p-3*s+1,M=p-2*s+x,d=-2*p+3*s,b=p-s;n.push([m*h[0]+M*u[0]+d*c[0]+b*l[0],m*h[1]+M*u[1]+d*c[1]+b*l[1]])}}return n}export function arcPts(t,e,n,r,o,a){const h=Math.max(4,Math.ceil(Math.abs(a-o)*Math.max(n,r)/3)),c=[];for(let u=0;u<=h;u++){const l=o+(a-o)*u/h;c.push([t+n*Math.cos(l),e+r*Math.sin(l)])}return c}export function curve(t,e=160){const n=[];for(let r=0;r<=e;r++)n.push(t(r/e));return n}export function join(...t){const e=[];for(const n of t)for(const r of n){const o=e[e.length-1];(!o||Math.hypot(r[0]-o[0],r[1]-o[1])>.4)&&e.push(r)}return e}export function resample(t,e=4){const n=[t[0][0]],r=[t[0][1]];let o=t[0][0],a=t[0][1],h=e;for(let l=1;l<t.length;l++){let y=t[l][0],f=t[l][1],i=Math.hypot(y-o,f-a);for(;i>=h;){const x=h/i;o+=(y-o)*x,a+=(f-a)*x,n.push(o),r.push(a),i-=h,h=e}h-=i,o=y,a=f}const c=t[t.length-1];(Math.hypot(c[0]-n[n.length-1],c[1]-r[r.length-1])>e*.35||n.length<2)&&(n.push(c[0]),r.push(c[1]));let u=0;for(let l=1;l<n.length;l++)u+=Math.hypot(n[l]-n[l-1],r[l]-r[l-1]);return{x:Float32Array.from(n),y:Float32Array.from(r),n:n.length,L:u}}export function makeRail(t,e={}){const n=resample(t);return{type:"rail",x:n.x,y:n.y,n:n.n,L:n.L,ds:n.L/(n.n-1),style:e.style??"tube",w:e.w??40,tier:e.tier??0,cruise:e.cruise??1,grav:e.grav??1,floor:e.floor??1,markers:(e.markers??[]).slice().sort((r,o)=>r.s-o.s),cap:e.cap??"both",joints:e.joints??!0}}export function makeAir(t,e,n,r={}){return{type:"air",x0:t[0],y0:t[1],x1:e[0],y1:e[1],h:Math.max(0,n),markers:r.markers??[],cup:!!r.cup,quiet:!!r.quiet,land:r.land??null,start:r.start??null}}export function railPoint(t,e,n){const r=Math.max(0,Math.min(t.L,e))/t.ds,o=Math.min(t.n-2,Math.floor(r)),a=r-o;return n.x=t.x[o]+(t.x[o+1]-t.x[o])*a,n.y=t.y[o]+(t.y[o+1]-t.y[o])*a,n.tx=(t.x[o+1]-t.x[o])/t.ds,n.ty=(t.y[o+1]-t.y[o])/t.ds,n}export const railEnd=t=>[t.x[t.n-1],t.y[t.n-1]];export function nearestS(t,e,n){let r=0,o=1e18;for(let a=0;a<t.n;a++){const h=(t.x[a]-e)**2+(t.y[a]-n)**2;h<o&&(o=h,r=a)}return r*t.ds}
